def enc(s):
    out = b''
    for ch in s:
        if ch == '\u20ac':
            out += b'\x80'
        else:
            try:
                out += ch.encode('cp936')
            except UnicodeEncodeError:
                out += ch.encode('utf-8')
    return out


for p in ['src/report.py', 'src/summary.py']:
    text = open(p, 'rb').read().decode('utf-8-sig')
    for line in text.splitlines():
        if '"""' in line:
            m = line.strip()[3:]
            raw = enc(m)
            print(p, raw)
            print('   ->', raw.decode('utf-8', 'replace'))
            print('   ->', raw.decode('utf-8', 'ignore'))

